"""The cp1 and maze scorer routes: generated by course_planner.make_routes, selected by refnav.launch."""
import json
import math
from pathlib import Path

import numpy as np
import pytest
import yaml

from nav.course_map import CourseMap
from nav.frames import load_launch
from nav.route_planner import _crossings
from refnav import map_route as M
from refnav.launch import ROUTE_NAMES, arguments, route_selection

ROOT = Path(__file__).resolve().parents[1]
CM = CourseMap.load(ROOT / "maps" / "course_sdf.npz")
YAML = ROOT / "maps" / "course.yaml"
HEIGHT = 0.7                         # main.py HEIGHT_M
KEYS = ("launch_sim", "launch")
GATE_A_X = 0.305


def _band(name, key):
    """The path refnav flies for a scorer route: the elastic band on the course map, in the map frame."""
    launch = load_launch(YAML, key)
    pts = json.loads((ROOT / "routes" / f"route_{name}_{key}.json").read_text())["route"]
    path = M.builder(CM, launch, HEIGHT + launch["z"], M.DRONE_RADIUS_M + 0.20, 0.3)(
        [(0.0, 0.0)] + [(f, -l) for f, l in pts])
    x, y = M.MapFrame(launch).to_map(path.x, path.y)
    return launch, path, np.c_[x, y]


@pytest.mark.parametrize("key", KEYS)
@pytest.mark.parametrize("name", ("cp1", "maze"))
def test_scorer_route_starts_at_the_launch_and_keeps_the_planned_clearance(name, key):
    launch, path, xy = _band(name, key)
    assert math.dist(xy[0], (launch["x"], launch["y"])) < 0.1      # the band nudges the real mark (0.41 m from a barrier) forward
    assert np.nanmin(path.clearance) >= 0.38                 # course.yaml: drone_radius 0.28 + clearance_margin 0.10


@pytest.mark.parametrize("key", KEYS)
def test_cp1_ends_past_checkpoint_1_and_maze_past_gate_a(key):
    cps = yaml.safe_load(YAML.read_text())["checkpoints"]

    def passed(name):
        xy = [tuple(p) for p in _band(name, key)[2]]
        return {c["checkpoint"] for c in _crossings(xy, HEIGHT, cps, {}, 0.28) if c.get("past_m", 0) > 0}
    assert passed("cp1") == {"CP1"}
    assert passed("maze") == {"CP1", "CP2"}
    assert _band("maze", key)[2][-1][0] > GATE_A_X


def test_scorer_routes_share_the_flown_route_params():
    flown = json.loads((ROOT / "route.json").read_text())["params"]
    for key in KEYS:
        for name in ("cp1", "maze"):
            doc = json.loads((ROOT / "routes" / f"route_{name}_{key}.json").read_text())
            assert doc["params"] == flown and all(len(p) == 2 for p in doc["route"])


def test_route_selection_names_files_by_launch_key(tmp_path):
    assert route_selection(ROOT, "full", "launch") == (ROOT / "route.json", "map")
    for name in ("cp1", "maze"):
        for key in KEYS:
            assert route_selection(ROOT, name, key) == (ROOT / "routes" / f"route_{name}_{key}.json", "file")
    with pytest.raises(ValueError, match="route_name"):
        route_selection(ROOT, "lap", "launch")
    with pytest.raises(ValueError, match="no cp1 route"):
        route_selection(tmp_path, "cp1", "launch_sim")
    assert ROUTE_NAMES == ("full", "cp1", "maze")


def test_arguments_pass_the_route_name():
    assert "route_name:=cp1" in arguments(ROOT, height_m=0.7, hover_s=2.0, route="cp1")
